  };

  const beginPushToTalk = () => {
		if (busy || recordingPromiseRef.current) return;
		setRecording(true);
		const pending = startMicRecording();
		recordingPromiseRef.current = pending;
		void pending.then((recorder) => {
			recorderRef.current = recorder;
