			recordingPromiseRef.current = null;
			setRecording(false);
			console.warn("[keating:stt] microphone unavailable", error);
		});
	};

	const finishPushToTalk = async () => {
		const pending = recordingPromiseRef.current;
		if (!pending) return;
		setRecording(false);
